          .replace(/"/g, "&quot;")
          .replace(/'/g, "&#39;");

      const validate = (values) => {
        const errors = {};
        if (!values.fullName.trim()) {
          errors.fullName = "Full name is required.";
        }
        if (!values.email.trim()) {
          errors.email = "Email address is required.";
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim())) {
          errors.email = "Enter a valid email address.";
        }
        return errors;
      };

      const Field = ({ id, label, type, value, placeholder, required, helperText, error, autocomplete }) => `
        <div class="form-field${error ? " error" : ""}">
          <label for="${id}">${escapeHtml(label)}${required ? ' <span class="required">*</span>' : ""}</label>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            value="${escapeHtml(value)}"
            placeholder="${escapeHtml(placeholder)}"
            ${required ? "required" : ""}
            ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
            aria-describedby="${id}-help ${error ? `${id}-error` : ""}".trim()
          />
          <p class="helper-text" id="${id}-help">${escapeHtml(helperText || "")}</p>
          <p class="error-text" id="${id}-error" aria-live="polite">${error ? escapeHtml(error) : ""}</p>
        </div>
      `;

